contract InvMutTest {
	C c;
	constructor(C _c) { c = _c; }

	// single public function that exercises AdjustBetAmounts and checks the bet limit behavior
	function runTest(uint256 initialLimit, uint256 amount) public {
		// Preconditions: owner-only — we assume test caller is the owner; otherwise calls will revert.
		// Set initial bet limit by calling AdjustBetAmounts with initialLimit (works on P where it sets)
		c.AdjustBetAmounts(initialLimit);
		// Now call AdjustBetAmounts with amount which on P sets betLimit = amount, but on M increments
		c.AdjustBetAmounts(amount);
		// Observe the publicly visible currentBetLimit()
		uint256 observed = c.currentBetLimit();
		// Assert that the observed limit equals amount (i.e., the last call replaced the limit)
		assert(observed == amount);
	}

	// Allow contract to receive Ether if needed by C functions
	receive() external payable {}
	fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        // precondition: caller must be the owner of C and the current betLimit must be 0 to avoid prior state influence
        require(msg.sender == address(c) ? false : true); // placeholder to keep structure; actual owner check done via observed behavior below
        // Ensure the contract's current bet limit is zero before the change
        require(c.currentBetLimit() == 0, "pre: betLimit must be 0");
        // Call AdjustBetAmounts as the caller; test harness assumes msg.sender is owner when running tests.
        c.AdjustBetAmounts(amount);
        // After increasing from 0, the resulting bet limit should be >= previous (0) and should not have wrapped to a smaller value.
        // General rule: currentBetLimit() >= 0 and <= amount (for original behavior it equals amount; for mutant it may wrap to small value when amount is huge)
        uint256 newLimit = c.currentBetLimit();
        assert(newLimit <= amount);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        // No precondition: owner check is enforced by C; non-owners will revert and the assert won't be evaluated.
        uint256 before = c.currentBetLimit();
        // call that modifies state
        c.AdjustBetAmounts(amount);
        uint256 after = c.currentBetLimit();
        // General rule: bet limit must not decrease after adjustment
        assert(after >= before);
