pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // We fuzz a nonzero initial owner-set bet limit and an arbitrary delta.
    // The fuzzer supplies initialLimit and delta. We will first set betLimit to initialLimit
    // by calling AdjustBetAmounts(initialLimit) from the owner (deployed contract owner is this),
    // then call AdjustBetAmounts(delta) and assert that the resulting currentBetLimit()
    // equals initialLimit + delta. This is a universal property the reference satisfies
    // for all inputs (when starting from the owner and using the contract's public methods);
    // the mutant that instead increments in a different way will produce a differing result
    // for some fuzzed inputs. We expose both parameters to the fuzzer.
    function testFuzz_property(uint256 initialLimit, uint256 delta) public {
        // keep values wide but avoid trivial degenerate where both zero (still allowed)
        // Bound them into a practical uint range to avoid overflow in the reference semantics
        initialLimit = bound(initialLimit, 0, type(uint256).max - 1);
        delta = bound(delta, 0, type(uint256).max - 1);

        // Call AdjustBetAmounts as owner (this contract is owner).
        // First set bet limit to initialLimit by calling AdjustBetAmounts(initialLimit).
        // Note: per constructor we deployed with wagerLimit 0; calling AdjustBetAmounts should
        // set betLimit (reference) to initialLimit. Then calling AdjustBetAmounts(delta) should
        // result in betLimit == initialLimit + delta on the reference.
        bool ok;
        try c.AdjustBetAmounts(initialLimit) {
            ok = true;
        } catch {
            // If this reverts, property doesn't hold for this input; fail the assertion
            ok = false;
        }
        // ensure first call succeeded
        assertTrue(ok);

        // Now call AdjustBetAmounts(delta)
        try c.AdjustBetAmounts(delta) {
            ok = true;
        } catch {
            ok = false;
        }
        // require second call succeeded as well
        assertTrue(ok);

        // Single assertion about c's public view: currentBetLimit() equals initialLimit + delta.
        // This is the universal property we check: after setting to initialLimit then adjusting by
        // delta, the resulting bet limit must equal initialLimit + delta. The mutant that
        // incorrectly implements AdjustBetAmounts will violate this for some inputs and cause a
        // failing test.
        assertTrue(c.currentBetLimit() == initialLimit + delta);
    }
}

