contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drives the contract and checks a single observable condition distinguishing P from M.
    // Params:
    // - ownerAddr: must be the owner of c (caller who can call onlyOwner functions)
    // - whaleAddr: any address used when originally deploying C (not used here but kept as context)
    // - betAmount: an amount that the owner will set as the bet limit and that a player will send to wager()
    // - player: the address that will call wager() and then play()
    // Note: This test assumes the caller of this function is the owner of c. The verifier will supply appropriate msg.sender.
    function runTest(address player, uint256 betAmount) public payable {
        // Precondition: this contract must hold at least betAmount to forward to wager()
        require(address(this).balance >= betAmount, "insufficient balance to wager");

        // 1) Owner (msg.sender) opens the game to public and sets the bet limit to betAmount.
        // These are state-changing calls that must be top-level statements.
        c.OpenToThePublic();
        c.AdjustBetAmounts(betAmount);

        // 2) The player (in this test we simulate player by having this contract call wager)
        // We first check that currentBetLimit equals the configured betAmount (observable).
        // On the original contract P this holds; on mutant M AdjustBetAmounts sets betLimit=0 so it will fail.
        uint256 configured = c.currentBetLimit();

        // require that configured equals the intended betAmount so that subsequent wager will be accepted
        require(configured == betAmount, "configured bet limit mismatch");

        // 3) Place a wager by forwarding betAmount to wager(); uses this contract as msg.sender (must be a real EOA in a real test harness)
        c.wager{value: betAmount}();

        // 4) Now assert that hasPlayerWagered(address(this)) returns true: the player (this contract) has an active wager.
        // This is the single assert required. On P this is true; on M AdjustBetAmounts set bet limit to 0 and the require in wager will revert or not accept the bet, so this will be false.
        assert(c.hasPlayerWagered(address(this)) == true);
    }

    // Allow contract to receive ETH so it can forward to c.wager
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // We need to call play() first. To satisfy C.play's onlyPlayers modifier, the caller must have a wager > 0.
    // To ensure that in contract P the betLimit is nonzero and wager() accepted some value earlier,
    // we require that currentBetLimit() is nonzero before running the test and that the caller is a player.
    function run() public payable {
        // Preconditions: contract currently allows public play and has a nonzero bet limit
        require(c.currentBetLimit() > 0, "betLimit must be > 0 for original contract");
        // Caller must have previously wagered according to c.hasPlayerWagered
        require(c.hasPlayerWagered(msg.sender), "caller must already be a player with a wager");

        // Establish the state the difference needs
        // Call play() as the player who wagered
        c.play();

        // Now perform the mutated action
        c.AdjustBetAmounts(1);

        // The general rule: after running these, the contract's currentBetLimit should remain nonzero
        // (Original contract preserves a nonzero bet limit set earlier; mutant sets it to zero.)
        assert(c.currentBetLimit() != 0);
    }

    receive() external payable { }
}

