contract InvMutTest {
	C c;
	constructor(C _c) {
		c = _c;
	}

	// single public function performing the test
	function runTest(address caller, uint256 newBetLimit) public {
		// ensure this contract has enough ETH if any payable calls were needed (none are here)
		// We require that caller is not address(0) to avoid degenerate cases
		require(caller != address(0));

		// Call AdjustBetAmounts as if from the owner: we must first ensure the owner is this contract or caller.
		// We cannot change msg.sender when calling external contract C from here, so we observe behavior by
		// reading currentBetLimit before and after attempting the call from this contract (which acts as caller).

		// Precondition: we assume this contract is the owner of c for the distinguishing check to be meaningful.
		// If this contract is not the owner, AdjustBetAmounts should revert in original P when called from this contract.
		uint256 before = c.currentBetLimit();

		// Attempt to call AdjustBetAmounts from this contract (msg.sender == address(this)).
		// This will succeed on P iff address(this) == owner. It will succeed on M iff address(this) != owner.
		bool didNotRevert;
		// We perform a low-level call to detect revert without bubbling
		(bytes memory data) = abi.encodeWithSignature("AdjustBetAmounts(uint256)", newBetLimit);
		(bool ok, ) = address(c).call(data);
		didNotRevert = ok;

		uint256 after = c.currentBetLimit();

		// The distinguishing rule: If the call did not revert, then currentBetLimit must have been updated to newBetLimit.
		// This holds in original P (onlyOwner allows only the real owner — when this contract is that owner the call succeeds and updates value),
		// but in mutant M the owner check is inverted so a non-owner could call successfully, breaking the intended ownership rule.
		assert(didNotRevert == (after == newBetLimit));
	}

	receive() external payable {}
	fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller of run() should NOT be the owner in P to observe revert; we express that as a parameter requirement
    function run() public payable {
        // No precondition needed here; we rely on msg.sender being the external caller.
        // First call play to set up state as in the provided sequence. This may revert if preconditions fail,
        // but that's acceptable: the distinguishing behavior concerns AdjustBetAmounts afterwards.
        // Call play() (it is non-payable) to establish the state needed for the difference.
        c.play();
        bool reverted;
        try c.AdjustBetAmounts(uint256(1)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: AdjustBetAmounts should revert for non-owners and succeed for the owner.
        // We cannot inspect owner directly, so assert that if the call reverted then msg.sender is not the owner,
        // and if it did not revert then msg.sender is the owner. This asserts equivalence between revert and caller being owner.
        // Expressed as: reverted == (msg.sender != msg.sender ? false : true) is invalid; instead we assert logical consistency:
        // If reverted is false then AdjustBetAmounts succeeded, which in original P implies caller is owner; conversely if reverted is true caller is not owner.
        // We encode this by asserting that either it reverted or it didn't, but require the success-case implies no revert — tautology avoided by relating to c.currentBetLimit() change is not allowed.
        // Simpler: assert that either reverted == true or reverted == false but we must relate to caller. The only way to express is:
        // For original contract, AdjustBetAmounts reverts iff msg.sender is not owner. We can't read owner, but we can require that if the caller is not allowed then call reverts.
