contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // fuzzer will supply two callers and an amount. The general rule:
    // In the reference, only the owner can change difficulty; calling AdjustBetAmounts
    // (which is owner-only) by any caller should NOT change difficulty value observable
    // after the call (i.e., difficulty remains what owner previously set). The mutant
    // flips onlyOwner and allows non-owners to affect owner-only behavior, so for some
    // fuzzed caller/address inputs difficulty observed after calls can differ.
    function testFuzz_property(address caller1, address caller2, uint256 amount) public {
        // Keep addresses non-zero to be meaningful
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        // Ensure the two callers are distinct to allow differing behavior
        vm.assume(caller1 != caller2);

        // Make sure the contract has some initial difficulty value (0 by default);
        // owner (this test contract) sets difficulty to a known nonzero via AdjustDifficulty
        // so we can observe whether AdjustBetAmounts (callable only by owner in reference)
        // ever changes difficulty. We pick an arbitrary difficulty and amount via fuzzed amount.
        uint256 initialDifficulty = (amount == 0 ? 1 : amount); // keep non-zero difficulty
        // only owner can call AdjustDifficulty on the reference; we are owner (setUp used address(this)).
        c.AdjustDifficulty(initialDifficulty);

        // Record difficulty before any AdjustBetAmounts calls
        uint256 before = c.currentDifficulty();

        // Now have caller1 call AdjustBetAmounts(amount). In the reference this is onlyOwner,
        // so non-owner calls should revert and not change difficulty. But the mutant permits
        // non-owners to call owner-only, which may change observable difficulty in some scenarios.
        bool ok1;
        vm.prank(caller1);
        try c.AdjustBetAmounts(amount) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // Record difficulty after first call
        uint256 after1 = c.currentDifficulty();

        // Have caller2 call AdjustBetAmounts(amount ^ 2) to create a potentially different input
        bool ok2;
        vm.prank(caller2);
        try c.AdjustBetAmounts(amount ^ 0xDEADBEEF) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        uint256 after2 = c.currentDifficulty();

        // GENERAL RULE (single assert): In the reference contract, AdjustBetAmounts is owner-only
        // so any non-owner call attempts won't change difficulty; therefore regardless of who calls
        // AdjustBetAmounts (caller1 or caller2) the difficulty should remain equal to `before`.
        // We assert that difficulty equals `before` now. The mutant inverts onlyOwner and will allow
        // some non-owner caller to successfully change state such that this assertion can fail
        // for some fuzzed inputs — making the test fail on the mutant but pass on reference.
        assertTrue(after2 == before, "difficulty changed by AdjustBetAmounts call when it should not");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive with owner-only calls: caller of this test must be owner of c.
    // We take two inputs: initial adjustment amount A1 to set betLimit to A1 on P,
    // then A2 to adjust again. On P, currentBetLimit() == A2 after second call
    // if A2 was the explicit set; on M it would be A1 + A2 (incrementing).
    function run(uint256 A1, uint256 A2) public {
        // preconditions: amounts non-zero to avoid degenerate equalities
        require(A1 > 0 && A2 > 0);
        // First call: set bet limit to A1 (on P) or increment by A1 (on M)
        c.AdjustBetAmounts(A1);
        // Second call: set bet limit to A2 (on P) or increment by A2 (on M)
        c.AdjustBetAmounts(A2);
        // Observe the resulting bet limit
        uint256 finalLimit = c.currentBetLimit();
        // On the original contract P, the second call sets betLimit == A2.
        // On mutant M, the second call results in finalLimit == A1 + A2.
        assert(finalLimit == A2);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }

    // single public function containing all test logic
    // params: amount to set (must be nonzero to avoid trivial halves matching) and a dummy address/value not used
    function run(uint256 amount) public {
        // require a meaningful input
        require(amount > 1);

        // call the function that was mutated
        c.AdjustBetAmounts(amount);

        // observe via the public getter currentBetLimit()
        uint256 observed = c.currentBetLimit();

        // On the original contract, AdjustBetAmounts sets betLimit = amount, so observed == amount.
        // On the mutant, it sets betLimit = amount/2, so the assertion will fail for many inputs.
        assert(observed == amount);
    }

    // allow the contract to receive ether (not used but safe)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function driving the contract and asserting the distinguishing property
    // params:
    //   newLimit - the value attempted to be set via AdjustBetAmounts
    //   caller - the address that will call AdjustBetAmounts (must be non-owner to test mutant)
    // Note: we cannot change msg.sender from here; instead we rely on the caller being provided
    // by the test harness (the verifier will call this function with different msg.senders).
    function run(uint256 newLimit, address caller) public {
        // read original bet limit
        uint256 original = c.currentBetLimit();

        // require that caller is not the owner to target the difference
        // We cannot read owner (it's private), so require caller != address(c) and rely on harness to choose non-owner.
        // To make a meaningful precondition we require caller not equal to address(this) to avoid ambiguous harness sender.
        require(caller != address(this));

        // The distinguishing call: attempt to set bet limit as `caller`
        // Must be an external transaction from `caller`; the verifier will simulate calling run with that msg.sender.
        // Here we make the external call through c.AdjustBetAmounts; the harness should set msg.sender == caller when invoking this function.
        // But Solidity does not allow setting msg.sender for internal calls; the intended use is verifier will execute run with tx.origin/caller semantics.
        // To ensure the call is executed as arising from this transaction sender, we call c.AdjustBetAmounts directly.
        c.AdjustBetAmounts(newLimit);

        // read new bet limit
        uint256 after = c.currentBetLimit();

        // The invariant that distinguishes original contract from mutant:
        // In original P only the owner can change betLimit, so if a non-owner (the test harness) invokes AdjustBetAmounts, betLimit must remain unchanged.
        assert(after == original);
    }

    // fallback and receive to allow sending/receiving ETH if needed by harness
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // we need to send exactly the bet limit value when calling wager/play in normal flows,
    // but we don't rely on reading betLimit. We only need play to execute (so precondition: caller has previously placed a wager by being a player).
    // However the provided counterexample sequence calls play() first, then AdjustBetAmounts().
    // To make play() succeed we require c to be openToPublic and that this contract has a wager recorded —
    // but we cannot call wager() easily without knowing betLimit. Instead we call play() directly and allow it to revert or not.
    // The distinguishing behavior is that AdjustBetAmounts reverts for non-owner on original but not on mutant. So we choose caller as non-owner.
    function run() public payable {
        require(true);
        // call play first as in the counterexample; allow it to succeed or revert (we don't check its revert here)
        // But per constraints, state-changing calls must be top-level. We call and ignore any revert by wrapping in try/catch.
        try c.play() {
            // nothing
        } catch {
            // ignored
        }
        bool reverted;
        // Call AdjustBetAmounts as non-owner (this contract is not necessarily the owner).
        // Use a param value for the new limit; choose arbitrary value 1.
        try c.AdjustBetAmounts(1) { reverted = false; } catch { reverted = true; }
        // In original contract onlyOwner modifier prevents non-owner from succeeding, so reverted must be true.
        // In mutant onlyOwner is relaxed so non-owner call would not revert. Hence assert that call reverted.
        assert(reverted == true);
    }
    receive() external payable { }
}

